-- SYNTHETIC LOCAL INTERFACES ONLY. No native pg_cron execution is modeled.
CREATE SCHEMA cron;
CREATE TABLE cron.job(jobid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,jobname text UNIQUE,schedule text,command text,database text DEFAULT current_database(),username text DEFAULT current_user,active boolean DEFAULT true);
CREATE TABLE cron.job_run_details(runid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,jobid bigint,status text,end_time timestamptz,return_message text);
CREATE FUNCTION cron.schedule(job_name text,schedule text,command text) RETURNS bigint LANGUAGE plpgsql AS $$DECLARE id bigint;BEGIN INSERT INTO cron.job(jobname,schedule,command) VALUES(job_name,schedule,command) RETURNING jobid INTO id;RETURN id;END$$;
CREATE FUNCTION cron.alter_job(job_id bigint,schedule text DEFAULT NULL,command text DEFAULT NULL,database text DEFAULT NULL,username text DEFAULT NULL,active boolean DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$BEGIN UPDATE cron.job j SET schedule=coalesce(alter_job.schedule,j.schedule),command=coalesce(alter_job.command,j.command),database=coalesce(alter_job.database,j.database),username=coalesce(alter_job.username,j.username),active=coalesce(alter_job.active,j.active) WHERE jobid=job_id;END$$;
REVOKE ALL ON SCHEMA cron FROM PUBLIC;
